// D3.js v6 Visualization for Stock Data

// Global variables
let stockData = [];
let bubbleChartSvg, tableContainer;
let selectedBubble = null, selectedRow = null;

// Load and process data
async function loadData() {
  try {
    // Load stock descriptions
    const csvText = await fetch('/data/stock-descriptions.csv').then(r => r.text());
    stockData = d3.csvParse(csvText);

    // Parse numeric fields
    stockData.forEach(d => {
      d.marketCap = d.marketCap ? parseFloat(d.marketCap) : null;
