  // Select new bubble and row
  selectedBubble = ticker;
  selectedRow = ticker;

  d3.selectAll('.bubble[data-ticker="' + ticker + '"] circle')
    .attr('stroke-width', 3)
    .attr('stroke', '#000');

  d3.select('tr[data-ticker="' + ticker + '"]')
    .attr('class', 'selected');

  // Scroll table row into view
  const rowElement = document.querySelector(`tr[data-ticker="${ticker}"]`);
  if (rowElement) {
    rowElement.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

